const fs = require('fs'), path = require('path');
const mk = d => { try { fs.mkdirSync(d, {recursive:true}) } catch {} };
mk('app/api/challenges');
fs.writeFileSync('app/api/challenges/route.js', Buffer.from('', 'base64'));
console.log('✓ app/api/challenges/route.js');
mk('app/api/group-contests');
fs.writeFileSync('app/api/group-contests/route.js', Buffer.from('', 'base64'));
console.log('✓ app/api/group-contests/route.js');
mk('app/api/leaderboard');
fs.writeFileSync('app/api/leaderboard/route.js', Buffer.from('', 'base64'));
console.log('✓ app/api/leaderboard/route.js');
mk('components');
fs.writeFileSync('components/CompeteTab.js', Buffer.from('', 'base64'));
console.log('✓ components/CompeteTab.js');
console.log('All done! Run: rd /s /q .next & npm run dev');